"""A policy made of stages that run one after the other: any navigation stage, then any manipulation stage.

    policy = make_sequential_policy([navigation_stage, manipulation_stage], handoff_after=0, ctx={})

The combining code knows nothing about what a stage does. A planner can replace the first stage and a learned policy (openpi) can replace the
second without any change here. The controller (src/control_loop.py) sees a single command source named "policy" with the optional functions
step(obs), status(), resume() and report(), and hz(): the rate of the stage that gave the latest commands.

A stage is a dictionary of callables:
    name (str)                  required. Shown as the "stage" of the status.
    step(obs) -> cmds           required. The commands for this tick (a command dictionary, a list of them, or None).
    done() -> bool              optional. True once the stage has finished its job. Default: never done (the last stage usually is not).
    error() -> str | None       optional. A message once the stage has failed. Default: no error.
    phase() -> str              optional. A label for the status ("DRIVE", "ARMS", "DONE", ...). A stage without one inherits the last label
                                of the stages before it.
    failure_outcome (str)       optional. The episode outcome to report when this stage fails. Default "POLICY_FAILED".
    observe(obs)                optional. Called every tick for every stage up to and including the current one, even after the stage is
                                done (measurements).
    restore(obs) -> None | (cmds, finished)
                                optional. Called every tick for stages that are done. None means nothing to restore; otherwise the stage
                                puts back something an operator moved: the commands to send and whether it is finished. While a done stage
                                is not finished the current stage is held back.
    resume()                    optional. Called when the operator hands control back, for every stage up to and including the current one.
    report() -> dict            optional. Added to the episode summary.
    report_top_level (bool)     optional. If true the keys of report() are also put at the top level of the combined report.
    hz (float)                  optional. The rate of the stage's commands in hertz; default the loop's tick rate. A stage with a lower rate (a
                                learned policy acts at 30 Hz) has step(obs) and restore(obs) called only on its due ticks (every n-th tick,
                                n = tick rate / hz, counted from tick 0) and gives no command on the others; so it must measure time with
                                obs["time"], not by counting calls. The loop ramps the arm and gripper targets over this period (the
                                "interpolate" target mode of src/control_loop.py), so the commands must come at this rate.
    state (dict)                optional. Free state, for tests.

Rules the combiner keeps: the next stage takes over on the tick AFTER the previous one reports done (so a stage's last tick is its own); the
timeout clock of the episode starts when stage `handoff_after` is done (None: from the start); the status reports the stage that is, or is
about to be, current.

The shared context dictionary `ctx` is created by the caller and passed to the stage builders and to the combiner, so stages can hand
results to later stages (a navigation stage can leave its final pose in it). It is available as policy["ctx"].

The module also provides two generic manipulation stages: make_hold_stage() and make_request_operator_stage().
"""


def make_hold_stage():
    """Builds a stage that commands nothing, so the arms hold where they are.

    Returns:
        dict: A stage with the name "hold", a step that returns None, and an empty state.
    """
    return {"name": "hold", "step": lambda obs: None, "state": {}}


def make_request_operator_stage(reason="manipulation is not implemented: operator control requested"):
    """Builds a stage that asks for operator control once and then holds.

    After the operator hands control back the stage simply keeps holding.

    Args:
        reason (str): The reason sent with the request (shown in the banner). Defaults to a message saying manipulation is not implemented.

    Returns:
        dict: A stage with the name "request_operator" whose state["requested"] says whether the request was sent.
    """
    state = {"requested": False}

    def step(obs):
        """Returns the request command the first time, None afterwards."""
        if not state["requested"]:
            state["requested"] = True
            return {"mode": "request_teleop", "reason": reason}
        return None

    return {"name": "request_operator", "step": step, "state": state}


def make_sequential_policy(stages, handoff_after=0, ctx=None):
    """Combines stages into one policy source for the control loop.

    Args:
        stages (list[dict]): The stages in order; see the module docstring for the stage dictionary. At least one.
        handoff_after (int | None): Index of the stage whose completion is the "handoff" (the moment the episode's timeout clock starts).
            None means there is no handoff and the clock starts at once. Defaults to 0.
        ctx (dict | None): Shared context dictionary for the stages. A new empty one is made if None. Defaults to None.

    Returns:
        dict: A command source with the keys
            "name" ("policy"), "step" (obs -> commands), "status" (() -> dict, see below), "resume" (() -> None),
            "report" (() -> dict), "hz" (() -> float or None, the "hz" of the stage that gave the latest commands), "stages" (the list given),
            "ctx" (the shared dictionary) and "state" ({"index": the index of the stage that stepped last, "emit_hz": its hz}).
        status() returns {"stage": name of the current stage, "phase": the label, "handoff": bool, "error": str | None} and, when there is an
        error, "failure_outcome": the failing stage's outcome name. report() returns {"stages": {stage name: its report}} plus the keys of
        every report whose stage has report_top_level set.

    Raises:
        ValueError: If `stages` is empty or `handoff_after` is not a valid index.
    """
    if not stages:
        raise ValueError("a sequential policy needs at least one stage")
    if handoff_after is not None and not 0 <= handoff_after < len(stages):
        raise ValueError(f"handoff_after {handoff_after} is not a stage index (0 to {len(stages) - 1})")
    ctx = {} if ctx is None else ctx
    state = {"index": 0, "emit_hz": None}
    last = len(stages) - 1

    def due(stage, obs):
        """True if the stage gives commands on this tick: it has no "hz", or the tick number is a multiple of tick rate / hz."""
        hz = stage.get("hz")
        if not hz:
            return True
        n = max(1, round(1.0 / (obs["timestep"] * obs["steps_per_frame"] * hz)))
        return obs["tick"] % n == 0

    def is_done(stage):
        """True if the stage has a done() and it says so."""
        return "done" in stage and bool(stage["done"]())

    def effective_index():
        """Index of the stage that is, or is about to be, current: the first one that is not done."""
        i = state["index"]
        while i < last and is_done(stages[i]):
            i += 1
        return i

    def status():
        """Builds the status the loop publishes as obs["policy"] (see make_sequential_policy)."""
        i = effective_index()
        phase = next((s["phase"]() for s in reversed(stages[:i + 1]) if "phase" in s), stages[i]["name"])
        error, outcome = None, None
        for s in stages[:i + 1]:
            if "error" in s and s["error"]():
                error, outcome = s["error"](), s.get("failure_outcome", "POLICY_FAILED")
                break
        out = {"stage": stages[i]["name"], "phase": phase,
               "handoff": True if handoff_after is None else is_done(stages[handoff_after]), "error": error}
        if error:
            out["failure_outcome"] = outcome
        return out

    def step(obs):
        """Runs one tick: observe, move on to the next stage if the current one was done, restore finished stages, then step the current one."""
        for s in stages[:state["index"] + 1]:
            if "observe" in s:
                s["observe"](obs)
        while state["index"] < last and is_done(stages[state["index"]]):    # a stage is replaced on the tick after it reported done
            state["index"] += 1
        for s in stages[:state["index"]]:
            if "restore" in s and due(s, obs):
                r = s["restore"](obs)
                if r is not None and not r[1]:
                    state["emit_hz"] = s.get("hz")
                    return r[0]
        cur = stages[state["index"]]
        state["emit_hz"] = cur.get("hz")
        return cur["step"](obs) if due(cur, obs) else None

    def resume():
        """Tells every stage up to and including the current one that the operator handed control back."""
        for s in stages[:effective_index() + 1]:
            if "resume" in s:
                s["resume"]()

    def report():
        """Collects the stage reports (see make_sequential_policy)."""
        out, nested = {}, {}
        for s in stages:
            if "report" in s:
                r = s["report"]()
                nested[s["name"]] = r
                if s.get("report_top_level"):
                    out.update(r)
        out["stages"] = nested
        return out

    return {"name": "policy", "step": step, "status": status, "resume": resume, "report": report, "stages": stages, "ctx": ctx, "state": state,
            "hz": lambda: state["emit_hz"]}
